import{_ as l,C as s,o as t,c as i,a0 as a,b as n,w as o,a as c,E as r,a1 as p}from"./chunks/framework.DeoJcRVf.js";const k=JSON.parse('{"title":"Despliegue de Flowex: credenciales, pipelines y pasos","description":"","frontmatter":{},"headers":[],"relativePath":"deployment.md","filePath":"deployment.md"}'),g={name:"deployment.md"};function u(y,e,h,f,x,m){const d=s("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="despliegue-de-flowex-credenciales-pipelines-y-pasos" tabindex="-1">Despliegue de Flowex: credenciales, pipelines y pasos <a class="header-anchor" href="#despliegue-de-flowex-credenciales-pipelines-y-pasos" aria-label="Permalink to &quot;Despliegue de Flowex: credenciales, pipelines y pasos&quot;">​</a></h1><p>Guía única para desplegar la plataforma completa: qué despliega cada repositorio, dónde vive cada credencial y en qué orden se levanta un ambiente.</p><div class="warning custom-block"><p class="custom-block-title">Ningún valor secreto va en esta guía ni en un repositorio</p><p>Aquí solo aparecen <strong>nombres</strong> y <strong>ubicaciones</strong>. Los valores se leen en AWS Secrets Manager, en GitHub o en el panel del proveedor. Este sitio es público.</p></div><blockquote><p>Estado verificado el 2026-10-10 contra el código de <code>Flowex-iac</code>, los workflows de cada repositorio y la configuración de GitHub de la organización <code>start-level-cl</code>. Si cambias un workflow, un secreto o un construct de CDK, actualiza esta página.</p></blockquote><hr><h2 id="_1-ambientes" tabindex="-1">1. Ambientes <a class="header-anchor" href="#_1-ambientes" aria-label="Permalink to &quot;1. Ambientes&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"><code>dev</code></th><th style="text-align:left;"><code>prod</code></th></tr></thead><tbody><tr><td style="text-align:left;">Cuenta AWS</td><td style="text-align:left;"><code>281414431636</code></td><td style="text-align:left;"><code>281414431636</code> (la misma cuenta y la misma VPC)</td></tr><tr><td style="text-align:left;">Región</td><td style="text-align:left;"><code>us-east-2</code></td><td style="text-align:left;"><code>us-east-2</code></td></tr><tr><td style="text-align:left;">Rama que despliega</td><td style="text-align:left;"><code>develop</code></td><td style="text-align:left;"><code>main</code></td></tr><tr><td style="text-align:left;">Stack principal</td><td style="text-align:left;"><code>FlowexStack-dev</code></td><td style="text-align:left;"><code>FlowexStack-prod</code></td></tr><tr><td style="text-align:left;">Stack de bootstrap (rol de despliegue)</td><td style="text-align:left;"><code>FlowexBootstrap-dev</code></td><td style="text-align:left;"><code>FlowexBootstrap-prod</code></td></tr><tr><td style="text-align:left;">Frontend</td><td style="text-align:left;"><code>https://dbf6cga0db80r.cloudfront.net</code></td><td style="text-align:left;"><code>https://flowex.inspytech.cl</code></td></tr><tr><td style="text-align:left;">Base de datos</td><td style="text-align:left;">PostgreSQL 16 <code>db.t3.micro</code>, sin multi-AZ, sin rotación</td><td style="text-align:left;"><code>db.t3.small</code>, multi-AZ, protección de borrado, rotación cada 30 días</td></tr><tr><td style="text-align:left;">Correos y WhatsApp</td><td style="text-align:left;">Desviados a una casilla y un número de prueba</td><td style="text-align:left;">Destinatario real</td></tr><tr><td style="text-align:left;">Horario de oficina</td><td style="text-align:left;">Lunes a viernes 08:30–20:00 (hora de Chile)</td><td style="text-align:left;">Siempre encendido</td></tr></tbody></table><p>La configuración de cada ambiente está en <code>Flowex-iac/lib/config/environments.ts</code>.</p><hr><h2 id="_2-que-despliega-cada-repositorio" tabindex="-1">2. Qué despliega cada repositorio <a class="header-anchor" href="#_2-que-despliega-cada-repositorio" aria-label="Permalink to &quot;2. Qué despliega cada repositorio&quot;">​</a></h2><p>Todos los pipelines se autentican en AWS por <strong>OIDC</strong>: no existen llaves de acceso de AWS guardadas en GitHub. Cada repositorio asume un rol <code>flowex-&lt;servicio&gt;-&lt;env&gt;-github-deploy-role</code>, que solo confía en su repositorio y en su rama (<code>develop</code> para dev, <code>main</code> para prod).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Repositorio</th><th style="text-align:left;">Workflow</th><th style="text-align:left;">Disparador</th><th style="text-align:left;">Qué hace</th><th style="text-align:left;">Destino</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Flowex-iac</code></td><td style="text-align:left;"><code>iac.yml</code></td><td style="text-align:left;">push/PR a <code>develop</code> o <code>main</code></td><td style="text-align:left;">Build, tests, <code>cdk synth</code> y <code>cdk diff</code>. <strong>No despliega.</strong></td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><code>Flowex-iac</code></td><td style="text-align:left;"><code>iac.yml</code></td><td style="text-align:left;">Manual (<code>workflow_dispatch</code>)</td><td style="text-align:left;"><code>action=deploy</code> despliega <code>FlowexBootstrap-&lt;env&gt;</code> y después <code>FlowexStack-&lt;env&gt;</code>. También <code>shutdown</code>, <code>office-start/stop</code> y <code>maintenance-*</code></td><td style="text-align:left;">CloudFormation</td></tr><tr><td style="text-align:left;"><code>Flowex-database</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">push a <code>develop</code> / <code>main</code></td><td style="text-align:left;">Empaqueta migraciones y semillas, actualiza <code>flowex-db-migrate-&lt;env&gt;</code> y la invoca con <code>action: up</code> (dev agrega <code>seed: true</code>)</td><td style="text-align:left;">Aurora/RDS vía Lambda en la VPC</td></tr><tr><td style="text-align:left;"><code>Flowex-auth-api-lambda</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">push a <code>develop</code> / <code>main</code></td><td style="text-align:left;">Tests, build, zip y <code>aws lambda update-function-code</code></td><td style="text-align:left;"><code>flowex-auth-api-&lt;env&gt;</code></td></tr><tr><td style="text-align:left;"><code>Flowex-auth-admin-lambda</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">ídem</td><td style="text-align:left;">ídem</td><td style="text-align:left;"><code>flowex-auth-admin-&lt;env&gt;</code></td></tr><tr><td style="text-align:left;"><code>Flowex-registration-public-lambda</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">ídem</td><td style="text-align:left;">ídem</td><td style="text-align:left;"><code>flowex-registration-public-&lt;env&gt;</code></td></tr><tr><td style="text-align:left;"><code>Flowex-registration-admin-lambda</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">ídem</td><td style="text-align:left;">ídem</td><td style="text-align:left;"><code>flowex-registration-admin-&lt;env&gt;</code></td></tr><tr><td style="text-align:left;"><code>Flowex-otp-service-lambda</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">ídem</td><td style="text-align:left;">ídem</td><td style="text-align:left;"><code>flowex-otp-service-&lt;env&gt;</code></td></tr><tr><td style="text-align:left;"><code>Flowex-otp-service-lambda</code></td><td style="text-align:left;"><code>whatsapp-templates.yml</code></td><td style="text-align:left;">Manual</td><td style="text-align:left;"><code>revisar</code> o <code>aplicar</code> las plantillas de Meta declaradas en el código</td><td style="text-align:left;">Cuenta de WhatsApp Business</td></tr><tr><td style="text-align:left;"><code>Flowex-payments-api-lambda</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">push a <code>develop</code> / <code>main</code></td><td style="text-align:left;">Tests, build, zip y actualización del código</td><td style="text-align:left;"><code>flowex-payments-api-&lt;env&gt;</code></td></tr><tr><td style="text-align:left;"><code>Flowex-notification-lambda</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">ídem</td><td style="text-align:left;">ídem</td><td style="text-align:left;"><code>flowex-notification-&lt;env&gt;</code></td></tr><tr><td style="text-align:left;"><code>Flowex-consent-worker-lambda</code></td><td style="text-align:left;"><code>deploy.yml</code></td><td style="text-align:left;">ídem</td><td style="text-align:left;">ídem</td><td style="text-align:left;"><code>flowex-consent-worker-&lt;env&gt;</code></td></tr><tr><td style="text-align:left;"><code>Flowex-frontend</code></td><td style="text-align:left;"><code>frontend-deploy.yml</code></td><td style="text-align:left;">push a <code>develop</code> / <code>main</code>, o manual</td><td style="text-align:left;">Lint, tests, build de Vite, subida a S3 e invalidación de CloudFront. Lee bucket, distribución y URL de la API desde los outputs del stack</td><td style="text-align:left;">Bucket S3 + CloudFront</td></tr><tr><td style="text-align:left;"><code>Flowex-api-docs</code></td><td style="text-align:left;"><code>vercel-deploy.yml</code></td><td style="text-align:left;">push a <code>main</code> (producción) y PR a <code>main</code> (preview)</td><td style="text-align:left;">Publica la carpeta <code>docs/</code> ya compilada</td><td style="text-align:left;">Vercel</td></tr></tbody></table><p><strong>Las Lambdas no se despliegan desde CDK.</strong> <code>FlowexStack</code> crea cada función con un handler de relleno (<code>&quot;pending first deploy&quot;</code>). El código real llega cuando corre el pipeline del repositorio de esa Lambda. Un stack recién creado responde 200 con un mensaje vacío en todas las rutas hasta que se despliega cada servicio.</p><p>Los workflows de las Lambdas usan Node 24 y pnpm 10. El de IaC usa la versión de <code>.nvmrc</code>, y el frontend usa Node 22.</p><hr><h2 id="_3-donde-viven-las-credenciales" tabindex="-1">3. Dónde viven las credenciales <a class="header-anchor" href="#_3-donde-viven-las-credenciales" aria-label="Permalink to &quot;3. Dónde viven las credenciales&quot;">​</a></h2><h3 id="_3-1-aws-secrets-manager-region-us-east-2" tabindex="-1">3.1 AWS Secrets Manager (región <code>us-east-2</code>) <a class="header-anchor" href="#_3-1-aws-secrets-manager-region-us-east-2" aria-label="Permalink to &quot;3.1 AWS Secrets Manager (región `us-east-2`)&quot;">​</a></h3><p>Las Lambdas reciben el <strong>nombre</strong> del secreto como variable de entorno y leen el valor en el arranque en frío. Ningún valor secreto viaja como variable de entorno en texto plano.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Secreto</th><th style="text-align:left;">Quién lo crea</th><th style="text-align:left;">Formato</th><th style="text-align:left;">Lo lee</th></tr></thead><tbody><tr><td style="text-align:left;"><code>flowex-postgres-&lt;env&gt;-credentials</code></td><td style="text-align:left;">CDK (generado)</td><td style="text-align:left;"><code>{ &quot;username&quot;: &quot;flowex_admin&quot;, &quot;password&quot;, ... }</code></td><td style="text-align:left;">Todas las Lambdas (<code>DB_SECRET_ARN</code>, usuario maestro de respaldo)</td></tr><tr><td style="text-align:left;"><code>flowex/&lt;env&gt;/db/app-user</code></td><td style="text-align:left;">CDK (generado)</td><td style="text-align:left;"><code>{ &quot;username&quot;: &quot;flowex_app&quot;, &quot;password&quot; }</code></td><td style="text-align:left;">Todas las Lambdas (<code>APP_DB_SECRET_ARN</code>). La migración 035 crea el rol con esta contraseña</td></tr><tr><td style="text-align:left;"><code>flowex/&lt;env&gt;/orders/delivery-pin-key</code></td><td style="text-align:left;">CDK (generado, <strong>RETAIN</strong>)</td><td style="text-align:left;">Texto de 64 caracteres</td><td style="text-align:left;"><code>auth-admin</code> (<code>DELIVERY_PIN_KEY_NAME</code>). Borrarlo deja ilegibles todos los códigos de entrega guardados</td></tr><tr><td style="text-align:left;"><code>flowex/prod/auth/root</code></td><td style="text-align:left;">CDK (generado, solo prod, <strong>RETAIN</strong>)</td><td style="text-align:left;"><code>{ email, name, rut, phone, password }</code></td><td style="text-align:left;"><code>db-migrate</code> crea la cuenta root la primera vez</td></tr><tr><td style="text-align:left;"><code>flowex/&lt;env&gt;/auth/jwt</code></td><td style="text-align:left;"><strong>A mano, antes del primer deploy</strong></td><td style="text-align:left;"><code>{ &quot;secret&quot;: &quot;&lt;valor&gt;&quot; }</code> (también acepta el valor solo)</td><td style="text-align:left;">Todas las Lambdas (<code>AUTH_JWT_SECRET_NAME</code>)</td></tr><tr><td style="text-align:left;"><code>flowex/&lt;env&gt;/mercadopago/checkout-pro</code></td><td style="text-align:left;"><strong>A mano</strong></td><td style="text-align:left;"><code>{ &quot;accessToken&quot;, &quot;publicKey&quot;, &quot;webhookSecret&quot; }</code></td><td style="text-align:left;"><code>payments-api</code> (<code>MP_SECRET_NAME</code>)</td></tr><tr><td style="text-align:left;"><code>flowex/&lt;env&gt;/fintoc/payments</code></td><td style="text-align:left;"><strong>A mano</strong></td><td style="text-align:left;"><code>{ &quot;secretKey&quot;, &quot;publicKey&quot;, &quot;webhookSecret&quot; }</code></td><td style="text-align:left;"><code>payments-api</code> (<code>FINTOC_SECRET_NAME</code>). Si falta, <code>/payments/fintoc/*</code> responde 503</td></tr><tr><td style="text-align:left;"><code>flowex/&lt;env&gt;/meta/whatsapp</code></td><td style="text-align:left;"><strong>A mano</strong></td><td style="text-align:left;"><code>{ &quot;apiToken&quot;, &quot;phoneNumberId&quot;, &quot;wabaId&quot;, &quot;senderNumber&quot; }</code></td><td style="text-align:left;"><code>otp-service</code> (<code>WHATSAPP_SECRET_NAME</code>) y <code>notification</code> (ver <a href="#_9-brechas-conocidas">brechas</a>)</td></tr><tr><td style="text-align:left;"><code>flowex/&lt;env&gt;/google/maps</code></td><td style="text-align:left;"><strong>A mano</strong></td><td style="text-align:left;"><code>{ &quot;apiKey&quot;: &quot;&lt;valor&gt;&quot; }</code></td><td style="text-align:left;"><code>auth-admin</code> (<code>GOOGLE_MAPS_SECRET_NAME</code>, Directions)</td></tr><tr><td style="text-align:left;"><code>flowex/&lt;env&gt;/google/route-optimization</code></td><td style="text-align:left;"><strong>A mano</strong></td><td style="text-align:left;">JSON completo de la cuenta de servicio de GCP (<code>client_email</code>, <code>private_key</code>, <code>token_uri</code>, ...)</td><td style="text-align:left;"><code>auth-admin</code> (<code>ROUTE_OPTIMIZATION_SECRET_NAME</code>)</td></tr></tbody></table><p>Crear un secreto manual (desde una máquina con credenciales de administrador):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secretsmanager</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-secret</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --region</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> us-east-2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flowex/prod/mercadopago/checkout-pro</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --secret-string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file://mp.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # archivo temporal; bórralo después</span></span></code></pre></div><p>Para cambiar un valor existente usa <code>aws secretsmanager put-secret-value</code>. Las Lambdas guardan las credenciales en caché mientras el contenedor siga vivo: Fintoc las refresca cada 5 minutos, y JWT, Mercado Pago y WhatsApp solo al arrancar en frío. Para forzar la lectura, vuelve a desplegar la Lambda o cambia su configuración.</p><div class="danger custom-block"><p class="custom-block-title">Rotar el secreto JWT cierra todas las sesiones</p><p>Cambiar <code>flowex/&lt;env&gt;/auth/jwt</code> invalida todos los tokens emitidos. En prod, avisa antes.</p></div><h3 id="_3-2-aws-ssm-parameter-store" tabindex="-1">3.2 AWS SSM Parameter Store <a class="header-anchor" href="#_3-2-aws-ssm-parameter-store" aria-label="Permalink to &quot;3.2 AWS SSM Parameter Store&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Parámetro</th><th style="text-align:left;">Quién lo escribe</th><th style="text-align:left;">Uso</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/shared/network/&lt;env&gt;/*</code> (<code>vpcId</code>, <code>vpcCidr</code>, <code>subnetCount</code>, <code>&lt;tier&gt;SubnetIds/&lt;i&gt;</code>, <code>ecsSecurityGroupId</code>, <code>rdsSecurityGroupId</code>, ...)</td><td style="text-align:left;">Stack <code>network-iac</code> (externo a Flowex)</td><td style="text-align:left;"><code>FlowexStack</code> importa la VPC desde aquí. <strong>Debe existir antes del primer deploy.</strong></td></tr><tr><td style="text-align:left;"><code>/flowex/&lt;env&gt;/s3/*</code>, <code>/flowex/&lt;env&gt;/cloudfront/*</code></td><td style="text-align:left;"><code>FlowexStack</code></td><td style="text-align:left;">Bucket y distribución del frontend</td></tr><tr><td style="text-align:left;"><code>/flowex/&lt;env&gt;/lambda/&lt;servicio&gt;-function-name</code> y <code>-function-arn</code></td><td style="text-align:left;"><code>FlowexStack</code></td><td style="text-align:left;">Nombres y ARNs de las Lambdas</td></tr><tr><td style="text-align:left;"><code>/flowex/&lt;env&gt;/sqs/consent-*</code>, endpoints y ARNs de Aurora/Postgres</td><td style="text-align:left;"><code>FlowexStack</code></td><td style="text-align:left;">Referencias para otros servicios</td></tr><tr><td style="text-align:left;"><code>/flowex/&lt;env&gt;/maintenance/bypass-key</code> (SecureString) y <code>/state</code></td><td style="text-align:left;"><code>scripts/maintenance-ctl.mjs</code></td><td style="text-align:left;">Llave y estado del <a href="/maintenance-mode">modo mantenimiento</a></td></tr><tr><td style="text-align:left;"><code>/cdk-bootstrap/hnb659fds/version</code></td><td style="text-align:left;"><code>cdk bootstrap</code></td><td style="text-align:left;">El workflow de IaC aborta si no existe</td></tr></tbody></table><h3 id="_3-3-github-actions-organizacion-start-level-cl" tabindex="-1">3.3 GitHub Actions (organización <code>start-level-cl</code>) <a class="header-anchor" href="#_3-3-github-actions-organizacion-start-level-cl" aria-label="Permalink to &quot;3.3 GitHub Actions (organización `start-level-cl`)&quot;">​</a></h3><p>Configurado a la fecha de esta guía:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Repositorio</th><th style="text-align:left;">Secrets</th><th style="text-align:left;">Variables</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Flowex-iac</code></td><td style="text-align:left;"><code>ERROR_SENTINEL_WEBHOOK_URL</code> (en el repo y en los entornos <code>development</code> y <code>production</code>)</td><td style="text-align:left;"><code>DEV_ACCOUNT_ID</code>, <code>DEV_REGION</code>, <code>PROD_ACCOUNT_ID</code>, <code>PROD_REGION</code>, <code>PROD_DOMAIN_NAME</code>, <code>PROD_APP_SUBDOMAIN</code>, <code>PROD_API_SUBDOMAIN</code>, <code>PROD_APP_CERTIFICATE_ARN</code>, <code>PROD_API_CERTIFICATE_ARN</code>, <code>PROD_SES_FROM_EMAIL</code>, <code>PROD_CONSENT_API_BASE_URL</code>, <code>PROD_CONSENT_REST_API_ID</code></td></tr><tr><td style="text-align:left;"><code>Flowex-frontend</code></td><td style="text-align:left;">—</td><td style="text-align:left;"><code>DEV_ACCOUNT_ID</code>, <code>DEV_REGION</code>, <code>PROD_ACCOUNT_ID</code>, <code>PROD_REGION</code>, <code>VITE_API_URL</code> (respaldo solo para staging), <code>VITE_FINTOC_ENABLED</code></td></tr><tr><td style="text-align:left;"><code>Flowex-api-docs</code></td><td style="text-align:left;"><code>VERCEL_TOKEN</code>, <code>VERCEL_ORG_ID</code></td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Repos de Lambdas y <code>Flowex-database</code></td><td style="text-align:left;">—</td><td style="text-align:left;">— (opcionales: <code>DEPLOY_ROLE_ARN</code> y <code>AWS_REGION</code> sobrescriben el rol y la región de dev)</td></tr></tbody></table><p>Para ver los nombres sin exponer valores, usa <code>gh secret list -R start-level-cl/&lt;repo&gt;</code> y <code>gh variable list -R start-level-cl/&lt;repo&gt;</code>. Para cargar un valor, usa <code>gh secret set NOMBRE -R start-level-cl/&lt;repo&gt;</code>, que lo pide por consola.</p><p>Variables opcionales que <code>Flowex-iac</code> lee si existen: <code>ALARM_EMAIL</code> (suscribe un correo a las alarmas), <code>LAMBDA_RESERVED_CONCURRENCY</code> (tope por función; requiere ampliar la cuota de concurrencia de la cuenta), <code>ROUTE_PLANNING_DAILY_LIMIT</code> (por defecto 2; <code>0</code> quita el tope) y <code>GCP_PROJECT_ID</code> (por defecto <code>flowex-losgistica</code>).</p><div class="tip custom-block"><p class="custom-block-title">La llave del webhook de alertas</p><p><code>ERROR_SENTINEL_WEBHOOK_URL</code> es el webhook de Discord del canal de alertas. Si falta, el stack se despliega sin centinela y sin reenvío de alarmas, en lugar de fallar.</p></div><h3 id="_3-4-proveedores-externos" tabindex="-1">3.4 Proveedores externos <a class="header-anchor" href="#_3-4-proveedores-externos" aria-label="Permalink to &quot;3.4 Proveedores externos&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Proveedor</th><th style="text-align:left;">Qué se obtiene ahí</th><th style="text-align:left;">Dónde se guarda</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Mercado Pago</strong> (panel de desarrolladores)</td><td style="text-align:left;">Access Token, Public Key, clave secreta del webhook</td><td style="text-align:left;"><code>flowex/&lt;env&gt;/mercadopago/checkout-pro</code></td></tr><tr><td style="text-align:left;"><strong>Fintoc</strong> (dashboard)</td><td style="text-align:left;"><code>sk_live_…</code>/<code>sk_test_…</code>, <code>pk_…</code>, secreto del webhook (se muestra una sola vez)</td><td style="text-align:left;"><code>flowex/&lt;env&gt;/fintoc/payments</code></td></tr><tr><td style="text-align:left;"><strong>Meta</strong> (WhatsApp Business)</td><td style="text-align:left;">Token permanente del usuario del sistema, Phone Number ID, WABA ID</td><td style="text-align:left;"><code>flowex/&lt;env&gt;/meta/whatsapp</code></td></tr><tr><td style="text-align:left;"><strong>Google Cloud</strong> (proyecto <code>flowex-losgistica</code>)</td><td style="text-align:left;">API key de Directions y cuenta de servicio con Route Optimization habilitado</td><td style="text-align:left;"><code>flowex/&lt;env&gt;/google/maps</code> y <code>flowex/&lt;env&gt;/google/route-optimization</code></td></tr><tr><td style="text-align:left;"><strong>Cloudflare</strong> (DNS de <code>inspytech.cl</code>)</td><td style="text-align:left;">Registros CNAME de <code>flowex.inspytech.cl</code> y de la API, y validación de los certificados ACM</td><td style="text-align:left;">No hay credencial en Flowex: los ARNs llegan por variables de GitHub</td></tr><tr><td style="text-align:left;"><strong>Amazon SES</strong></td><td style="text-align:left;">Identidad verificada del remitente</td><td style="text-align:left;"><code>PROD_SES_FROM_EMAIL</code> en GitHub. Dev usa una casilla verificada en sandbox</td></tr><tr><td style="text-align:left;"><strong>Discord</strong></td><td style="text-align:left;">Webhook del canal de alertas</td><td style="text-align:left;">Secret <code>ERROR_SENTINEL_WEBHOOK_URL</code> en <code>Flowex-iac</code></td></tr><tr><td style="text-align:left;"><strong>Vercel</strong></td><td style="text-align:left;">Token de la cuenta (vercel.com/account/tokens)</td><td style="text-align:left;">Secret <code>VERCEL_TOKEN</code> en <code>Flowex-api-docs</code></td></tr><tr><td style="text-align:left;"><strong>API central de consentimiento</strong></td><td style="text-align:left;">URL base y REST API ID</td><td style="text-align:left;">Prod: variables <code>PROD_CONSENT_*</code>. Dev: valores por defecto en <code>environments.ts</code></td></tr></tbody></table><h3 id="_3-5-desarrollo-local" tabindex="-1">3.5 Desarrollo local <a class="header-anchor" href="#_3-5-desarrollo-local" aria-label="Permalink to &quot;3.5 Desarrollo local&quot;">​</a></h3><p>Solo se usan archivos <code>.env</code> locales, que <strong>no se versionan</strong>. Los ejemplos están en <code>Flowex-frontend/.env.example</code>, <code>Flowex-database/.env.example</code> y <code>Flowex-payments-api-lambda/.env.example</code>. Las Lambdas aceptan el valor directo (<code>AUTH_JWT_SECRET</code>, <code>MP_ACCESS_TOKEN</code>, <code>FINTOC_SECRET_KEY</code>, <code>GOOGLE_MAPS_API_KEY</code>, ...) para pruebas locales. En AWS siempre se usa el secreto.</p><hr><h2 id="_4-requisitos-previos-una-vez-por-ambiente" tabindex="-1">4. Requisitos previos (una vez por ambiente) <a class="header-anchor" href="#_4-requisitos-previos-una-vez-por-ambiente" aria-label="Permalink to &quot;4. Requisitos previos (una vez por ambiente)&quot;">​</a></h2><ol><li><strong>Red compartida:</strong> <code>network-iac</code> desplegado, con sus parámetros en <code>/shared/network/&lt;env&gt;/*</code>.</li><li><strong>CDK bootstrap</strong> en la cuenta y región, con una identidad de administrador:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aws://281414431636/us-east-2</span></span></code></pre></div></li><li><strong>Proveedor OIDC de GitHub</strong> (<code>token.actions.githubusercontent.com</code>) creado en IAM.</li><li><strong>Rol de despliegue de IaC:</strong> desplegar <code>FlowexBootstrap-&lt;env&gt;</code> por primera vez con una identidad de administrador. Ese stack crea <code>flowex-iac-&lt;env&gt;-github-deploy-role</code>, que usa el workflow:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Flowex-iac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ENVIRONMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">prod</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FlowexBootstrap-prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exclusively</span></span></code></pre></div></li><li><strong>Secretos manuales</strong> de la <a href="#_3-1-aws-secrets-manager-region-us-east-2">sección 3.1</a> creados en Secrets Manager. Como mínimo, <code>flowex/&lt;env&gt;/auth/jwt</code> debe existir antes del primer deploy de las Lambdas: sin él, todas fallan cerradas.</li><li><strong>Variables de GitHub</strong> de la <a href="#_3-3-github-actions-organizacion-start-level-cl">sección 3.3</a> cargadas en <code>Flowex-iac</code> y <code>Flowex-frontend</code>.</li><li><strong>Solo prod:</strong><ul><li>Certificados ACM emitidos y validados para la app (en <code>us-east-1</code>, como exige CloudFront) y para la API (en <code>us-east-2</code>), con sus ARNs en <code>PROD_APP_CERTIFICATE_ARN</code> y <code>PROD_API_CERTIFICATE_ARN</code>.</li><li>Identidad de SES verificada para <code>PROD_SES_FROM_EMAIL</code>, y la cuenta SES fuera del sandbox.</li><li><code>PROD_CONSENT_API_BASE_URL</code> y <code>PROD_CONSENT_REST_API_ID</code> definidos. Sin ellos, el worker de consentimiento falla a propósito en vez de escribir en dev.</li></ul></li><li><strong>Cuota de concurrencia de Lambda:</strong> la cuenta tenía un límite de 10 ejecuciones simultáneas para todas las funciones (cuota <code>L-B99A9384</code>). Con ese límite, una ráfaga de tráfico devuelve 500 en API Gateway. Revísala en Service Quotas antes de abrir prod al público.</li></ol><hr><h2 id="_5-levantar-un-ambiente-desde-cero" tabindex="-1">5. Levantar un ambiente desde cero <a class="header-anchor" href="#_5-levantar-un-ambiente-desde-cero" aria-label="Permalink to &quot;5. Levantar un ambiente desde cero&quot;">​</a></h2><p>El orden importa: cada paso necesita lo que crea el anterior.</p>',41)),(t(),n(p,null,{default:o(()=>[r(d,{id:"mermaid-956",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B1.%20Requisitos%20previos%3Cbr%2F%3Ered%2C%20bootstrap%2C%20secretos%5D%20--%3E%20B%5B2.%20Flowex-iac%3Cbr%2F%3Eaction%3Ddeploy%5D%0A%20%20B%20--%3E%20C%5B3.%20Flowex-database%3Cbr%2F%3Emigraciones%5D%0A%20%20C%20--%3E%20D%5B4.%20Repos%20de%20Lambdas%3Cbr%2F%3E8%20servicios%5D%0A%20%20D%20--%3E%20E%5B5.%20Flowex-frontend%5D%0A%20%20E%20--%3E%20F%5B6.%20Webhooks%2C%20DNS%3Cbr%2F%3Ey%20plantillas%20de%20WhatsApp%5D%0A%20%20F%20--%3E%20G%5B7.%20Verificaci%C3%B3n%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<ol><li><strong>Infraestructura.</strong> En GitHub, abre <em>Flowex-iac → Actions → Flowex IaC CI/CD → Run workflow</em>. Para prod usa la rama <code>main</code> con <code>target_env=prod</code> y <code>action=deploy</code>; para dev, <code>develop</code> con <code>target_env=dev</code>. Desde la CLI:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iac.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start-level-cl/Flowex-iac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target_env=prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> action=deploy</span></span></code></pre></div>El job borra el stack si quedó en <code>ROLLBACK_COMPLETE</code>, despliega <code>FlowexBootstrap-&lt;env&gt;</code> y luego <code>FlowexStack-&lt;env&gt;</code>. Al terminar existen la base, las colas, el API Gateway, el bucket y la distribución, los roles OIDC de cada repositorio y las Lambdas con código de relleno.</li><li><strong>Base de datos.</strong> Haz push (o merge) a la rama del ambiente en <code>Flowex-database</code>. El pipeline sube el código a <code>flowex-db-migrate-&lt;env&gt;</code> y ejecuta las migraciones pendientes. En prod también crea la cuenta root desde <code>flowex/prod/auth/root</code>. La contraseña inicial se consulta en Secrets Manager y luego se cambia desde la app.</li><li><strong>Lambdas.</strong> Haz push o merge a la rama del ambiente en cada uno de los 8 repositorios de Lambdas. Si no hay cambios nuevos, un commit vacío también dispara el pipeline.</li><li><strong>Frontend.</strong> Haz push o merge en <code>Flowex-frontend</code>, o ejecútalo a mano con <code>target_env</code>. El build toma la URL de la API desde los outputs del stack. En prod prefiere el dominio propio y, si el CNAME todavía no responde, cae a la URL de <code>execute-api</code>.</li><li><strong>Integraciones externas.</strong><ul><li><strong>Cloudflare:</strong> crea el CNAME de la API apuntando al output <code>ApiCustomDomainTarget</code> y el de la app apuntando a la distribución de CloudFront.</li><li><strong>Mercado Pago:</strong> el webhook es <code>https://&lt;api&gt;/webhooks/mercadopago</code> (el stack lo entrega a la Lambda como <code>MP_NOTIFICATION_URL</code>). Configura la misma URL y su clave secreta en el panel.</li><li><strong>Fintoc:</strong> registra <code>https://&lt;api&gt;/webhooks/fintoc</code> en el dashboard y guarda el secreto del webhook en <code>flowex/&lt;env&gt;/fintoc/payments</code>.</li><li><strong>Plantillas de WhatsApp:</strong> <em>Flowex-otp-service-lambda → Actions → Plantillas de WhatsApp</em>, primero con <code>revisar</code> y después con <code>aplicar</code>. Meta tarda en aprobar las plantillas, y sin ellas los avisos fuera de la ventana de 24 horas no llegan.</li></ul></li><li><strong>Verificación.</strong> Sigue los pasos de la <a href="#_7-verificacion-despues-de-desplegar">sección 7</a>.</li></ol><hr><h2 id="_6-despliegue-del-dia-a-dia" tabindex="-1">6. Despliegue del día a día <a class="header-anchor" href="#_6-despliegue-del-dia-a-dia" aria-label="Permalink to &quot;6. Despliegue del día a día&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Cambio</th><th style="text-align:left;">Qué hacer</th></tr></thead><tbody><tr><td style="text-align:left;">Código de una Lambda</td><td style="text-align:left;">Merge a <code>develop</code> (dev) o a <code>main</code> (prod) en su repositorio. Se despliega solo.</td></tr><tr><td style="text-align:left;">Migración SQL</td><td style="text-align:left;">Merge en <code>Flowex-database</code>. Se aplica sola. Las migraciones no se revierten automáticamente: revisa el SQL antes de llevarlo a <code>main</code>.</td></tr><tr><td style="text-align:left;">Frontend</td><td style="text-align:left;">Merge en <code>Flowex-frontend</code>.</td></tr><tr><td style="text-align:left;">Infraestructura (<code>Flowex-iac</code>)</td><td style="text-align:left;">El merge <strong>solo</strong> ejecuta synth y diff. Revisa el <code>cdk diff</code> del job y luego ejecuta el workflow manual con <code>action=deploy</code>.</td></tr><tr><td style="text-align:left;">Documentación (<code>Flowex-api-docs</code>)</td><td style="text-align:left;"><code>pnpm build</code> (regenera <code>generated/</code> y <code>docs/</code>), commit y merge a <code>main</code>. Lo que solo esté en <code>develop</code> no se publica.</td></tr><tr><td style="text-align:left;">Un secreto</td><td style="text-align:left;"><code>aws secretsmanager put-secret-value</code>, y después redesplegar o reiniciar las Lambdas que lo leen.</td></tr></tbody></table><p>Cuando un cambio toca varios repositorios, el orden seguro es <strong>IaC → base de datos → Lambdas → frontend</strong>. Cada capa debe aceptar todavía lo que envía la anterior.</p><hr><h2 id="_7-verificacion-despues-de-desplegar" tabindex="-1">7. Verificación después de desplegar <a class="header-anchor" href="#_7-verificacion-despues-de-desplegar" aria-label="Permalink to &quot;7. Verificación después de desplegar&quot;">​</a></h2><ol><li><strong>Workflows en verde:</strong> <code>gh run list -R start-level-cl/&lt;repo&gt; --limit 3</code>.</li><li><strong>Infraestructura:</strong> no confíes solo en el resultado del workflow. Ejecuta <code>ENVIRONMENT=&lt;env&gt; npx cdk diff FlowexStack-&lt;env&gt;</code>: no debería mostrar cambios. Si algo no cuadra, revisa en CloudTrail quién actualizó el stack.</li><li><strong>Lambdas con código real:</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lambda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get-function</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --function-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flowex-auth-api-prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --query</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Configuration.[LastModified,CodeSize]&#39;</span></span></code></pre></div>Un <code>CodeSize</code> de pocos cientos de bytes significa que todavía tiene el handler de relleno.</li><li><strong>Migraciones:</strong> la salida del job de <code>Flowex-database</code> muestra <code>Applied N migration(s)</code> y <code>ok: true</code>.</li><li><strong>Prueba funcional:</strong> login, creación de un pedido y un pago de prueba. Las colecciones de <code>Flowex-bruno</code> cubren la API.</li><li><strong>Alarmas:</strong> el canal de Discord recibe errores de las Lambdas y cambios de alarmas. Con el centinela activo, una DLQ con mensajes avisa sola.</li></ol><hr><h2 id="_8-operacion-y-precauciones" tabindex="-1">8. Operación y precauciones <a class="header-anchor" href="#_8-operacion-y-precauciones" aria-label="Permalink to &quot;8. Operación y precauciones&quot;">​</a></h2><ul><li><strong>No despliegues el stack desde una máquina local</strong> (incluido WSL) si no es estrictamente necesario. Ya ocurrió dos veces (el 17-09 y el 28-09) que un <code>cdk deploy</code> local con código desactualizado revirtió el stack. Si es inevitable, haz <code>git pull</code> y revisa <code>cdk diff</code> antes de desplegar.</li><li><strong>Prod solo se despliega desde <code>main</code>.</strong> Los roles OIDC de prod rechazan otras ramas.</li><li><strong><code>shutdown</code> está bloqueado en prod.</strong> En dev despliega el stack con <code>SHUTDOWN=true</code>, lo que desactiva la planificación de rutas, el horario de oficina y el centinela. Los recursos se detienen con <code>Flowex-iac/scripts/stop-infra.ps1</code> (bastión, crons, bases de dev y NAT Gateways) y se recuperan con <code>restore-infra.ps1</code>. <strong>Ojo:</strong> el script elimina los NAT Gateways de la VPC compartida, que prod también usa.</li><li><strong>Modo mantenimiento y horario de oficina:</strong> ver <a href="/maintenance-mode">Modo Mantenimiento</a> y el README de <code>Flowex-iac</code>. Ambos existen solo en dev.</li><li><strong>Secretos con RETAIN:</strong> <code>delivery-pin-key</code> y <code>auth/root</code> sobreviven al borrado del stack. No los borres a mano.</li><li><strong>Rotación de la base en prod:</strong> la contraseña del usuario maestro rota cada 30 días por la Lambda <code>flowex-postgres-rotation-prod</code>. No la copies a ningún lado: léela siempre del secreto.</li></ul><hr><h2 id="_9-brechas-conocidas" tabindex="-1">9. Brechas conocidas <a class="header-anchor" href="#_9-brechas-conocidas" aria-label="Permalink to &quot;9. Brechas conocidas&quot;">​</a></h2><p>Detectadas al escribir esta guía y pendientes de corrección en el código:</p><ol><li><strong><code>flowex-notification-&lt;env&gt;</code> no tiene permiso sobre <code>flowex/&lt;env&gt;/meta/whatsapp</code>.</strong> La Lambda lee ese secreto (<code>src/whatsapp-client.ts</code>), pero <code>lambdas.ts</code> solo otorga el permiso a <code>otp-service</code>. Los WhatsApp que envía el worker de notificaciones fallarían con <code>AccessDenied</code>. Falta agregar <code>whatsappSecretStatement</code> a <code>notificationLambda</code>.</li><li><strong>El workflow de plantillas de WhatsApp nunca se ha ejecutado,</strong> y el rol que usa por defecto (<code>flowex-otp-service-dev-github-deploy-role</code>) solo tiene permisos para actualizar la Lambda: no puede leer outputs de CloudFormation ni secretos. Tampoco cambia de rol cuando <code>target_env=prod</code>. Hay que probarlo y ampliar o separar el rol antes de usarlo.</li><li><strong><code>CONSENT_API_BASE_URL</code></strong> se pasa al job de IaC, pero <code>environments.ts</code> lee <code>DEV_CONSENT_API_BASE_URL</code>. Dev funciona porque usa el valor por defecto; la variable no tiene efecto.</li><li><strong>Rol de despliegue de <code>consent-worker</code> en dev:</strong> se creó a mano y no está en CDK (solo el de prod). Si se borra, el pipeline de dev de ese repositorio queda sin rol.</li><li><strong><code>Flowex-shared-layer</code> no existe como repositorio ni como Lambda Layer desplegada.</strong> Cada Lambda incluye su propia copia de las utilidades compartidas.</li></ol>',15))])}const v=l(g,[["render",u]]);export{k as __pageData,v as default};
